public class ListNode
{
    public int val;
    public ListNode? next;
    public ListNode(int val, ListNode? next = null) { this.val = val; this.next = next; }
}

// Used by the tests:
static ListNode? FromArray(int[] values) { ListNode? head = null; for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head); return head; }
static int[] ToArray(ListNode? node) { var list = new List<int>(); for (; node != null; node = node.next) list.Add(node.val); return list.ToArray(); }

questions.answer:
public ListNode? ReverseList(ListNode? head)
{
    ListNode? prev = null;
    while (head != null)
    {
        var next = head.next; // remember the rest before overwriting the link
        head.next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

public int MaxSubArray(int[] nums)
{
    int best = nums[0], current = nums[0];
    for (int i = 1; i < nums.Length; i++)
    {
        current = Math.Max(nums[i], current + nums[i]); // extend the run, or start again here
        best = Math.Max(best, current);
    }
    return best;
}

public int[][] Merge(int[][] intervals)
{
    var result = new List<int[]>();
    foreach (var interval in intervals.OrderBy(i => i[0]))
    {
        if (result.Count > 0 && interval[0] <= result[^1][1])
            result[^1][1] = Math.Max(result[^1][1], interval[1]);
        else
            result.Add(new[] { interval[0], interval[1] });
    }
    return result.ToArray();
}

