public bool IsAnagram(string s, string t)
{
    if (s.Length != t.Length) return false;
    var counts = new Dictionary<char, int>();
    foreach (var c in s) counts[c] = counts.GetValueOrDefault(c) + 1;
    foreach (var c in t)
    {
        if (counts.GetValueOrDefault(c) == 0) return false;
        counts[c]--;
    }
    return true;
}

public int LengthOfLongestSubstring(string s)
{
    var lastSeen = new Dictionary<char, int>();
    int start = 0, best = 0;
    for (int i = 0; i < s.Length; i++)
    {
        // Only jump forward: an old occurrence before the window doesn't matter ("abba").
        if (lastSeen.TryGetValue(s[i], out var j) && j >= start) start = j + 1;
        lastSeen[s[i]] = i;
        best = Math.Max(best, i - start + 1);
    }
    return best;
}

public int ClimbStairs(int n)
{
    int a = 1, b = 1; // ways to reach steps i-2 and i-1
    for (int i = 2; i <= n; i++) (a, b) = (b, a + b);
    return b;
}

public IList<IList<string>> GroupAnagrams(string[] words)
{
    var groups = new Dictionary<string, IList<string>>();
    foreach (var word in words)
    {
        var chars = word.ToCharArray();
        Array.Sort(chars);
        var key = new string(chars); // anagrams share the same sorted letters
        if (!groups.TryGetValue(key, out var group)) groups[key] = group = new List<string>();
        group.Add(word);
    }
    return groups.Values.ToList();
}

