questions.answer:
public int[] TopKFrequent(int[] nums, int k)
{
    var counts = new Dictionary<int, int>();
    foreach (var n in nums) counts[n] = counts.GetValueOrDefault(n) + 1;

    // Min-heap of size k, keyed by count: the least frequent of the current top k is on top.
    var heap = new PriorityQueue<int, int>();
    foreach (var (value, count) in counts)
    {
        heap.Enqueue(value, count);
        if (heap.Count > k) heap.Dequeue();
    }
    var result = new int[heap.Count];
    for (int i = 0; i < result.Length; i++) result[i] = heap.Dequeue();
    return result;
}

public int NumIslands(char[][] grid)
{
    int islands = 0;
    for (int r = 0; r < grid.Length; r++)
        for (int c = 0; c < grid[r].Length; c++)
            if (grid[r][c] == '1') { islands++; Sink(grid, r, c); }
    return islands;
}

void Sink(char[][] grid, int r, int c)
{
    var stack = new Stack<(int, int)>();
    stack.Push((r, c));
    while (stack.Count > 0)
    {
        var (y, x) = stack.Pop();
        if (y < 0 || x < 0 || y >= grid.Length || x >= grid[y].Length || grid[y][x] != '1') continue;
        grid[y][x] = '0'; // mark visited
        stack.Push((y + 1, x)); stack.Push((y - 1, x)); stack.Push((y, x + 1)); stack.Push((y, x - 1));
    }
}
